# IMPERIA COLD WAR — Disposable native treaty execution and bilateral investment assertions
from native_fixture import source as observer_source


def source():
    def test(condition,name):return f'if = {{ limit = {{ {condition} }} log = "ICSD_NATIVE PASS {name}" }} else = {{ log = "ICSD_NATIVE FAIL {name}" }}'
    base=observer_source().replace('set_variable = { icsd_tab = 2 }','set_variable = { icsd_tab = 3 } set_variable = { icsd_history = 1 }')
    parts=[
      'log = "ICSD_NATIVE INFO TREATY_BEGIN"',
      'add_political_power = 1000 SOV = { add_political_power = 1000 }',
      'create_equipment_variant = { name = "ICWT PROBE ICBM1" type = nuclear_missile_equipment_1 allow_without_tech = yes } create_equipment_variant = { name = "ICWT PROBE ICBM2" type = nuclear_missile_equipment_2 allow_without_tech = yes }',
      'SOV = { create_equipment_variant = { name = "ICWT PROBE ICBM1" type = nuclear_missile_equipment_1 allow_without_tech = yes } }',
      'add_equipment_to_stockpile = { type = nuclear_missile_equipment_1 producer = USA variant_name = "ICWT PROBE ICBM1" amount = 400 }',
      'SOV = { add_equipment_to_stockpile = { type = nuclear_missile_equipment_1 producer = SOV variant_name = "ICWT PROBE ICBM1" amount = 800 } }',
      'log = "ICSD_NATIVE INFO reserve_counter model=[?num_equipment@nuclear_missile_equipment_1] archetype=[?num_equipment@nuclear_missile_equipment]"',
      test('check_variable = { num_equipment@nuclear_missile_equipment_1 > 399 } SOV = { check_variable = { num_equipment@nuclear_missile_equipment_1 > 799 } }','treaty_model_counters_read_real_nonzero_fixture_stocks'),
      test('has_equipment = { nuclear_missile_equipment_1 > 399 }','treaty_native_stored_model_trigger_nonzero'),
      'set_variable = { icwt_probe_model_one = num_equipment@nuclear_missile_equipment_1 } set_variable = { icwt_probe_model_two = num_equipment@nuclear_missile_equipment_2 } add_to_variable = { icwt_probe_model_two = 80 } add_equipment_to_stockpile = { type = nuclear_missile_equipment_2 producer = USA variant_name = "ICWT PROBE ICBM2" amount = 80 }',
      test('check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_model_one } check_variable = { num_equipment@nuclear_missile_equipment_2 = icwt_probe_model_two }','treaty_model_counters_distinguish_two_real_models'),
      'set_variable = { icwt_probe_usa_before = num_equipment@nuclear_missile_equipment_1 }',
      'SOV = { set_variable = { icwt_probe_sov_before = num_equipment@nuclear_missile_equipment_1 } }',
      'icwt_edit_5 = yes add_to_array = { icwt_edit_invites = FRA.id } icwt_send_5 = yes',
      test('NOT = { has_idea = icwt_spirit_5 } SOV = { NOT = { has_idea = icwt_spirit_5 } } check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_usa_before }','treaty_proposal_has_no_asset_or_spirit_effect'),
      'SOV = { icwt_sign_5 = yes }',test('SOV = { NOT = { has_idea = icwt_spirit_5 } }','treaty_signature_requires_review'),
      'set_variable = { icwt_probe_usa_expected = icwt_probe_usa_before } subtract_from_variable = { icwt_probe_usa_expected = icwt_plan_5_0 }',
      'subtract_from_variable = { icwt_probe_model_two = icwt_plan_5_1 }',
      'SOV = { set_variable = { icwt_probe_sov_expected = icwt_probe_sov_before } subtract_from_variable = { icwt_probe_sov_expected = icwt_plan_5_0 } icwt_review_5 = yes icwt_sign_5 = yes }',
      test('has_idea = icwt_spirit_5 SOV = { has_idea = icwt_spirit_5 }','treaty_both_core_spirits_native'),
      test('check_variable = { global.icwt_relief = 1 }','treaty_existing_cold_war_relief_cache'),
      test('check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_usa_expected } SOV = { check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_sov_expected } }','treaty_real_native_reserve_retirement'),
      test('check_variable = { num_equipment@nuclear_missile_equipment_2 = icwt_probe_model_two }','treaty_second_model_actual_native_retirement'),
      'SOV = { icwt_sign_5 = yes }',test('SOV = { check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_sov_expected } }','treaty_repeat_signature_no_retirement_replay'),
      test('check_variable = { global.icwt_5_members^num = 2 } FRA = { NOT = { has_idea = icwt_spirit_5 } }','treaty_optional_invitee_does_not_block_or_join'),
      'FRA = { icwt_review_5 = yes icwt_accept_invite_5 = yes }',test('FRA = { has_idea = icwt_spirit_5 } check_variable = { global.icwt_5_members^num = 3 }','treaty_native_late_accession'),
      'SOV = { icwt_leave_5 = yes }',test('has_idea = icwt_spirit_5 SOV = { NOT = { has_idea = icwt_spirit_5 } } FRA = { has_idea = icwt_spirit_5 }','treaty_withdrawal_preserves_other_signatories'),
      'icwt_edit_9 = yes icwt_send_9 = yes SOV = { icwt_review_9 = yes icwt_sign_9 = yes }',
      test('check_variable = { icwt_investment@SOV = 1 } SOV = { check_variable = { icwt_investment@USA = 1 } }','treaty_native_bilateral_investment_pair'),
      # A staging slot in the investor, selected state in PREV, actual controller as recipient.
      'set_variable = { project_building_type^-1 = 1 } set_variable = { project_build_amount^-1 = 1 }',
      'set_variable = { icwt_probe_pair_saved = icwt_investment@SOV } set_variable = { icwt_investment@SOV = 0 } SOV = { set_variable = { icwt_investment@USA = 0 } }',
      'SOV = { capital_scope = { USA = { project_monetary_cost_calculation = yes set_variable = { icwt_probe_cost_before = project_monetary_cost^-1 } } } }',
      'set_variable = { icwt_investment@SOV = icwt_probe_pair_saved } SOV = { set_variable = { icwt_investment@USA = PREV.icwt_probe_pair_saved } }',
      'SOV = { capital_scope = { USA = { project_monetary_cost_calculation = yes } } }',
      'log = "ICSD_NATIVE INFO investment_cost base=[?global.build_cost_array^1] type=[?project_building_type^-1] amount=[?project_build_amount^-1] before=[?icwt_probe_cost_before] after=[?project_monetary_cost^-1] factor=[?displayable_monetary_cost_modifier] pair=[?SOV.icwt_investment@USA]"',
      test('check_variable = { var = project_monetary_cost^-1 value = icwt_probe_cost_before compare = less_than }','treaty_real_native_investment_cost_discount'),
      'SOV = { set_variable = { icwt_investment@USA = 0 } capital_scope = { PREV.PREV = { PREV = { precompute_state_construction_data = yes } } } } set_variable = { icwt_probe_duration_before = receiving_investment_duration_temp }',
      'SOV = { set_variable = { icwt_investment@USA = PREV.icwt_probe_pair_saved } capital_scope = { PREV.PREV = { PREV = { precompute_state_construction_data = yes } } } }',
      'log = "ICSD_NATIVE INFO investment_duration before=[?icwt_probe_duration_before] after=[?receiving_investment_duration_temp]"',
      test('check_variable = { var = receiving_investment_duration_temp value = icwt_probe_duration_before compare = less_than }','treaty_real_native_investment_duration_discount'),
      'ENG = { PREV = { icwt_invite_active_9 = yes } } ENG = { icwt_review_9 = yes icwt_accept_invite_9 = yes }',
      test('ENG = { has_idea = icwt_spirit_9 } check_variable = { global.icwt_9_members^num = 3 }','treaty_active_invitation_real_third_party_consent'),
      'SOV = { icwt_leave_9 = yes }',test('check_variable = { icwt_investment@SOV = 0 }','treaty_native_departure_clears_investment_discount'),
      'icwt_edit_11 = yes set_variable = { icwt_edit_sanctions = 2 } add_to_array = { imp_fin_sanc_by_us = SOV.id } SOV = { add_to_array = { imp_fin_sanc_on_us = USA.id } }',
      'set_variable = { icwt_probe_pp = political_power } subtract_from_variable = { icwt_probe_pp = 35 }',
      'icwt_send_11 = yes SOV = { icwt_review_11 = yes icwt_sign_11 = yes }',
      test('NOT = { is_in_array = { array = imp_fin_sanc_by_us value = SOV } } SOV = { NOT = { is_in_array = { array = imp_fin_sanc_on_us value = USA } } }','treaty_native_sanction_mirrors_removed'),
      test('check_variable = { political_power = icwt_probe_pp }','treaty_native_sanction_fee_once'),
      test('check_variable = { icwt_block_fin@SOV = 1 }','treaty_native_selected_class_moratorium'),
      'icwt_leave_11 = yes',test('check_variable = { icwt_block_fin@SOV = 0 }','treaty_native_withdrawal_ends_moratorium'),
      'icwt_edit_8 = yes set_variable = { icwt_edit_duration = 180 } icwt_send_8 = yes SOV = { icwt_review_8 = yes icwt_sign_8 = yes } icwt_expire_8 = yes',
      test('has_idea = icwt_spirit_8','treaty_old_expiry_cannot_end_a_future_term'),
      'set_variable = { global.icwt_8_end = global.num_days } icwt_expire_8 = yes icwt_weekly = yes',
      test('NOT = { has_idea = icwt_spirit_8 } SOV = { NOT = { has_idea = icwt_spirit_8 } } check_variable = { global.icwt_8_members^num = 0 }','treaty_native_finite_expiry_cleanup'),
      'icwt_edit_1 = yes set_variable = { icwt_edit_reduction = 50 } icwt_send_1 = yes SOV = { set_variable = { icwt_probe_sov_assets = num_equipment@nuclear_missile_equipment_1 } } set_temp_variable = { icwt_probe_empty = num_equipment@nuclear_missile_equipment_1 } multiply_temp_variable = { icwt_probe_empty = -1 } add_equipment_to_stockpile = { type = nuclear_missile_equipment_1 amount = icwt_probe_empty }',
      'log = "ICSD_NATIVE INFO changed_stock pending=[?global.icwt_pending] scope=[?global.icwt_p_scope] reduction=[?global.icwt_p_reduction] actual=[?num_equipment@nuclear_missile_equipment_1] promised=[?icwt_plan_1_0]"',
      test('check_variable = { var = num_equipment@nuclear_missile_equipment_1 value = icwt_plan_1_0 compare = less_than }','treaty_probe_sender_inventory_below_frozen_promise'),
      'SOV = { icwt_review_1 = yes icwt_sign_1 = yes }',
      test('NOT = { has_idea = icwt_spirit_1 } SOV = { NOT = { has_idea = icwt_spirit_1 } check_variable = { num_equipment@nuclear_missile_equipment_1 = icwt_probe_sov_assets } } check_variable = { global.icwt_pending = 1 }','treaty_changed_stock_aborts_both_core_transactions'),
      'icwt_cancel_pending = yes',
      'set_variable = { icsd_tab = 2 } set_variable = { icwt_template = 5 } set_variable = { icwt_category = 1 } clear_variable = icwt_screen icwt_display = yes set_country_flag = icsd_open',
      'log = "ICSD_NATIVE INFO TREATY_END"',
    ]
    return base.replace('log = "ICSD_NATIVE COMPLETE"','\n'.join(parts)+'\nlog = "ICSD_NATIVE COMPLETE"')
